#!/usr/bin/env python3
from pathlib import Path
import re

path=Path.cwd()/'generated/AstroSathi/App.tsx'
if not path.exists(): raise SystemExit('Generated App.tsx not found')
text=path.read_text()
text=text.replace("{screen==='chart'&&<ChartScreen t={t} chart={chart} back={()=>setScreen('home')}/>}","{screen==='chart'&&<ChartScreen t={t} l={l} chart={chart} back={()=>setScreen('home')}/>}" ,1)

pattern=r"function ChartScreen\(.*?\nfunction PremiumScreen"
replacement=r'''const RASHI_UI:any={en:['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'],hi:['मेष','वृषभ','मिथुन','कर्क','सिंह','कन्या','तुला','वृश्चिक','धनु','मकर','कुंभ','मीन'],or:['ମେଷ','ବୃଷ','ମିଥୁନ','କର୍କଟ','ସିଂହ','କନ୍ୟା','ତୁଳା','ବିଛା','ଧନୁ','ମକର','କୁମ୍ଭ','ମୀନ']};
const GRAHA_UI:any={en:{Sun:'Sun',Moon:'Moon',Mercury:'Mercury',Venus:'Venus',Mars:'Mars',Jupiter:'Jupiter',Saturn:'Saturn',Rahu:'Rahu',Ketu:'Ketu'},hi:{Sun:'सूर्य',Moon:'चंद्र',Mercury:'बुध',Venus:'शुक्र',Mars:'मंगल',Jupiter:'बृहस्पति',Saturn:'शनि',Rahu:'राहु',Ketu:'केतु'},or:{Sun:'ସୂର୍ଯ୍ୟ',Moon:'ଚନ୍ଦ୍ର',Mercury:'ବୁଧ',Venus:'ଶୁକ୍ର',Mars:'ମଙ୍ଗଳ',Jupiter:'ବୃହସ୍ପତି',Saturn:'ଶନି',Rahu:'ରାହୁ',Ketu:'କେତୁ'}};
const rashiUI=(l:any,name:string)=>{const i=['Aries','Taurus','Gemini','Cancer','Leo','Virgo','Libra','Scorpio','Sagittarius','Capricorn','Aquarius','Pisces'].indexOf(name);return i>=0?RASHI_UI[l][i]:name};
const grahaUI=(l:any,name:string)=>GRAHA_UI[l]?.[name]||name;
function ChartScreen({t,l,chart,back}:any){if(!chart)return<ScrollView contentContainerStyle={s.page}><Back t={t} go={back}/><Text style={s.title}>{t.noChart}</Text></ScrollView>;const ui=l==='hi'?{vedic:'वैदिक कुंडली',lagna:'लग्न',maha:'महादशा',ends:'समाप्ति',panchang:'पंचांग',planets:'ग्रह स्थिति',house:'भाव',calc:'गणना पद्धति',explain:'आपकी कुंडली का सरल अर्थ'}:l==='or'?{vedic:'ବୈଦିକ କୁଣ୍ଡଳୀ',lagna:'ଲଗ୍ନ',maha:'ମହାଦଶା',ends:'ଶେଷ',panchang:'ପଞ୍ଚାଙ୍ଗ',planets:'ଗ୍ରହ ସ୍ଥିତି',house:'ଭାବ',calc:'ଗଣନା ପଦ୍ଧତି',explain:'ଆପଣଙ୍କ କୁଣ୍ଡଳୀର ସରଳ ଅର୍ଥ'}:{vedic:'VEDIC CHART',lagna:'Lagna',maha:'Mahadasha',ends:'Ends',panchang:'PANCHANG',planets:'PLANETARY POSITIONS',house:'House',calc:'CALCULATION STANDARD',explain:'WHAT YOUR KUNDLI MEANS'};return<ScrollView contentContainerStyle={s.page}><Back t={t} go={back}/><Text style={s.kicker}>{ui.vedic}</Text><Text style={s.title}>{rashiUI(l,chart.ascendant.rashi)} {ui.lagna}</Text><View style={s.row}><Metric k={ui.lagna} v={`${rashiUI(l,chart.ascendant.rashi)} ${chart.ascendant.degreesInRashi.toFixed(2)}°`} x={`${chart.ascendant.nakshatra} • Pada ${chart.ascendant.pada}`}/><Metric k={ui.maha} v={grahaUI(l,chart.dasha.currentLord)} x={`${ui.ends} ${new Date(chart.dasha.currentEndsAt).toLocaleDateString(l==='hi'?'hi-IN':l==='or'?'or-IN':'en-IN')}`}/></View><Card><Text style={s.gold}>{ui.panchang}</Text><Text style={s.cardTitle}>{chart.panchang.paksha} • {chart.panchang.tithi}</Text><Text style={s.muted}>{chart.panchang.nakshatra} P{chart.panchang.pada} · {chart.panchang.yoga} · {chart.panchang.karana}</Text></Card><Card><Text style={s.gold}>{ui.planets}</Text>{chart.planets.map((p:any)=><View style={s.planet} key={p.name}><View><Text style={s.white}>{grahaUI(l,p.name)}{p.retrograde?' R':''}</Text><Text style={s.small}>{p.nakshatra} P{p.pada}</Text></View><View style={{alignItems:'flex-end'}}><Text style={s.white}>{rashiUI(l,p.rashi)} {p.degreesInRashi.toFixed(2)}°</Text><Text style={s.small}>{ui.house} {p.house} · D9 {rashiUI(l,p.navamsa)}</Text></View></View>)}</Card><KundliMeaning chart={chart} l={l}/><Card><Text style={s.gold}>{ui.calc}</Text><Text style={s.muted}>{l==='hi'?'खगोलीय स्थिति Astronomy Engine, लाहिड़ी/चित्रपक्ष अयनांश, mean lunar nodes और whole-sign भाव पद्धति से निकाली गई है।':l==='or'?'ଖଗୋଳୀୟ ସ୍ଥିତି Astronomy Engine, ଲାହିଡ଼ୀ/ଚିତ୍ରପକ୍ଷ ଅୟନାଂଶ, mean lunar nodes ଏବଂ whole-sign ଭାବ ପଦ୍ଧତିରେ ଗଣନା କରାଯାଇଛି।':`${chart.ephemeris} · Lahiri/Chitrapaksha-style ayanamsha · mean lunar nodes · whole-sign houses.`}</Text></Card><Text style={s.disc}>{t.disc}</Text></ScrollView>}
function KundliMeaning({chart,l}:any){const moon=chart.planets.find((x:any)=>x.name==='Moon'),d=chart.dasha,loc=l==='hi'?'hi-IN':l==='or'?'or-IN':'en-IN';const date=(x:number)=>new Date(x).toLocaleDateString(loc);const houses=l==='hi'?['स्वयं, शरीर और व्यक्तित्व','परिवार, वाणी और धन','साहस, संचार और भाई-बहन','घर, माता, सुख और मूल शिक्षा','बुद्धि, रचनात्मकता, प्रेम और संतान','सेवा, प्रतियोगिता, ऋण और स्वास्थ्य चुनौतियाँ','विवाह और साझेदारी','परिवर्तन, गहरे विषय और साझा संसाधन','धर्म, उच्च शिक्षा, भाग्य और लंबी यात्रा','करियर, कर्म और सामाजिक प्रतिष्ठा','लाभ, आय, मित्र और नेटवर्क','खर्च, नींद, विदेश और आध्यात्मिक निवृत्ति']:l==='or'?['ନିଜ ସ୍ୱଭାବ, ଶରୀର ଓ ବ୍ୟକ୍ତିତ୍ୱ','ପରିବାର, କଥାବାର୍ତ୍ତା ଓ ଧନ','ସାହସ, ଯୋଗାଯୋଗ ଓ ଭାଇ-ଭଉଣୀ','ଘର, ମା, ସୁଖ ଓ ମୂଳ ଶିକ୍ଷା','ବୁଦ୍ଧି, ସୃଜନଶୀଳତା, ପ୍ରେମ ଓ ସନ୍ତାନ','ସେବା, ପ୍ରତିଯୋଗିତା, ଋଣ ଓ ସ୍ୱାସ୍ଥ୍ୟ ଚ୍ୟାଲେଞ୍ଜ','ବିବାହ ଓ ଭାଗୀଦାରୀ','ପରିବର୍ତ୍ତନ, ଗଭୀର ବିଷୟ ଓ ସଂଯୁକ୍ତ ସମ୍ପଦ','ଧର୍ମ, ଉଚ୍ଚ ଶିକ୍ଷା, ଭାଗ୍ୟ ଓ ଦୀର୍ଘ ଯାତ୍ରା','କ୍ୟାରିୟର, କର୍ମ ଓ ସାମାଜିକ ସ୍ଥାନ','ଲାଭ, ଆୟ, ମିତ୍ର ଓ ନେଟୱର୍କ','ଖର୍ଚ୍ଚ, ନିଦ୍ରା, ବିଦେଶ ଓ ଆଧ୍ୟାତ୍ମିକ ନିବୃତ୍ତି']:['self, body and outward personality','family, speech and accumulated wealth','courage, communication and siblings','home, mother, comfort and foundational education','intelligence, creativity, romance and children','service, competition, debt and health challenges','marriage and partnerships','transformation, deeper matters and shared resources','dharma, higher study, fortune and long journeys','career, actions and public standing','gains, income, friends and networks','expenses, sleep, foreign matters and spiritual withdrawal'];const x=l==='hi'?{title:'आपकी कुंडली का सरल अर्थ',what:'यह कुंडली क्या है?',whatText:'यह आपके जन्म की तारीख, सही समय और सत्यापित जन्म-स्थान पर उस क्षण ग्रहों और लग्न की पारंपरिक वैदिक ज्योतिषीय तस्वीर है। इसका उपयोग जीवन के अलग-अलग क्षेत्रों को समझने के लिए किया जाता है।',lagna:'लग्न क्या बताता है?',lagnaText:`आपका लग्न ${rashiUI(l,chart.ascendant.rashi)} है। लग्न वह राशि है जो जन्म के समय पूर्वी क्षितिज पर उठ रही थी। पारंपरिक ज्योतिष में यह आपके बाहरी व्यक्तित्व, जीवन की दिशा और 12 भावों की शुरुआत तय करता है।`,moon:'चंद्र राशि और नक्षत्र',moonText:`चंद्र ${moon?rashiUI(l,moon.rashi):'-'} राशि और ${chart.panchang.nakshatra} नक्षत्र में है। पारंपरिक रूप से चंद्र मन, भावनात्मक प्रतिक्रिया, आदतों और मानसिक सहजता से जोड़ा जाता है; नक्षत्र उस पैटर्न को और सूक्ष्म रूप देता है।`,dasha:'वर्तमान दशा का अर्थ',dashaText:`अभी ${grahaUI(l,d.currentLord)} महादशा, ${grahaUI(l,d.currentAntardashaLord)} अंतरदशा और ${grahaUI(l,d.currentPratyantarLord)} प्रत्यंतर चल रहा है। महादशा लंबा मुख्य चरण है, अंतरदशा उसके भीतर का उप-चरण और प्रत्यंतर उससे भी छोटा सक्रिय चरण है। वर्तमान महादशा ${date(d.currentEndsAt)} तक है।`,panch:'पंचांग क्या बताता है?',panchText:'तिथि चंद्र-सूर्य के कोणीय संबंध का दिन है; पक्ष बढ़ते या घटते चंद्र चरण को बताता है; नक्षत्र चंद्र की तारामंडलीय स्थिति है; योग और करण पारंपरिक पंचांग के अतिरिक्त समय-सूचक हैं।',d9:'D9 / नवांश क्या है?',d9Text:'D9 या नवांश मुख्य जन्म-कुंडली का एक विभाजित चार्ट है। पारंपरिक ज्योतिष में इसका उपयोग ग्रहों की सूक्ष्म शक्ति, धर्म और विशेष रूप से विवाह/साझेदारी के अतिरिक्त संदर्भ के लिए किया जाता है।',retro:'R का अर्थ',retroText:'किसी ग्रह के नाम के पास R का अर्थ retrograde है—पृथ्वी से देखने पर वह ग्रह पीछे चलता हुआ दिखाई देता है। यह वास्तविक उलटी गति नहीं, बल्कि दृश्य ज्यामितीय प्रभाव है; ज्योतिष में इसकी अलग व्याख्या की जाती है।',houses:'12 भावों का सरल अर्थ',accuracy:'सटीकता के लिए जरूरी',accuracyText:'सही जन्म-तारीख, यथासंभव सटीक जन्म-समय और सही जन्म-स्थान सबसे महत्वपूर्ण हैं। कुछ मिनट का समय-अंतर लग्न/भाव सीमा के पास परिणाम बदल सकता है। ज्योतिषीय अर्थ पारंपरिक व्याख्या है, वैज्ञानिक रूप से सिद्ध भविष्यवाणी नहीं।'}:l==='or'?{title:'ଆପଣଙ୍କ କୁଣ୍ଡଳୀର ସରଳ ଅର୍ଥ',what:'ଏହି କୁଣ୍ଡଳୀ କଣ?',whatText:'ଆପଣଙ୍କ ଜନ୍ମ ତାରିଖ, ସଠିକ୍ ସମୟ ଓ ସତ୍ୟାପିତ ଜନ୍ମସ୍ଥାନ ଅନୁଯାୟୀ ସେହି ମୁହୂର୍ତ୍ତର ଲଗ୍ନ ଓ ଗ୍ରହସ୍ଥିତିର ପାରମ୍ପରିକ ବୈଦିକ ଜ୍ୟୋତିଷ ଚିତ୍ର ହେଉଛି କୁଣ୍ଡଳୀ। ଜୀବନର ଭିନ୍ନ କ୍ଷେତ୍ରକୁ ବୁଝିବା ପାଇଁ ଏହା ବ୍ୟବହାର କରାଯାଏ।',lagna:'ଲଗ୍ନ କଣ କୁହେ?',lagnaText:`ଆପଣଙ୍କ ଲଗ୍ନ ${rashiUI(l,chart.ascendant.rashi)}। ଜନ୍ମ ସମୟରେ ପୂର୍ବ ଦିଗନ୍ତରେ ଉଦୟ ହେଉଥିବା ରାଶିକୁ ଲଗ୍ନ କୁହାଯାଏ। ପାରମ୍ପରିକ ଜ୍ୟୋତିଷରେ ଏହା ବାହ୍ୟ ବ୍ୟକ୍ତିତ୍ୱ, ଜୀବନ ଦିଗ ଓ 12ଟି ଭାବର ଆରମ୍ଭ ନିର୍ଦ୍ଧାରଣ କରେ।`,moon:'ଚନ୍ଦ୍ର ରାଶି ଓ ନକ୍ଷତ୍ର',moonText:`ଚନ୍ଦ୍ର ${moon?rashiUI(l,moon.rashi):'-'} ରାଶି ଏବଂ ${chart.panchang.nakshatra} ନକ୍ଷତ୍ରରେ ଅଛନ୍ତି। ପାରମ୍ପରିକ ଭାବେ ଚନ୍ଦ୍ର ମନ, ଭାବନା, ଅଭ୍ୟାସ ଓ ମାନସିକ ପ୍ରତିକ୍ରିୟା ସହ ଜଡିତ; ନକ୍ଷତ୍ର ସେହି ପ୍ରକୃତିକୁ ଆଉ ସୂକ୍ଷ୍ମ କରେ।`,dasha:'ବର୍ତ୍ତମାନ ଦଶାର ଅର୍ଥ',dashaText:`ଏବେ ${grahaUI(l,d.currentLord)} ମହାଦଶା, ${grahaUI(l,d.currentAntardashaLord)} ଅନ୍ତର୍ଦଶା ଏବଂ ${grahaUI(l,d.currentPratyantarLord)} ପ୍ରତ୍ୟନ୍ତର ଚାଲିଛି। ମହାଦଶା ଦୀର୍ଘ ମୁଖ୍ୟ ପର୍ଯ୍ୟାୟ, ଅନ୍ତର୍ଦଶା ତାହାର ଭିତର ଉପପର୍ଯ୍ୟାୟ ଏବଂ ପ୍ରତ୍ୟନ୍ତର ତାଠାରୁ ଛୋଟ ସକ୍ରିୟ ପର୍ଯ୍ୟାୟ। ବର୍ତ୍ତମାନ ମହାଦଶା ${date(d.currentEndsAt)} ପର୍ଯ୍ୟନ୍ତ।`,panch:'ପଞ୍ଚାଙ୍ଗ କଣ କୁହେ?',panchText:'ତିଥି ସୂର୍ଯ୍ୟ-ଚନ୍ଦ୍ରଙ୍କ କୋଣିକ ସମ୍ପର୍କ ଅନୁଯାୟୀ ଚନ୍ଦ୍ରଦିନ; ପକ୍ଷ ଚନ୍ଦ୍ର ବଢ଼ୁଛି କି କମୁଛି ତାହା କୁହେ; ନକ୍ଷତ୍ର ଚନ୍ଦ୍ରଙ୍କ ତାରାମଣ୍ଡଳୀୟ ସ୍ଥାନ; ଯୋଗ ଓ କରଣ ପାରମ୍ପରିକ ପଞ୍ଚାଙ୍ଗର ଅନ୍ୟ ସମୟ ସୂଚକ।',d9:'D9 / ନବାଂଶ କଣ?',d9Text:'D9 କିମ୍ବା ନବାଂଶ ମୁଖ୍ୟ ଜନ୍ମକୁଣ୍ଡଳୀର ଏକ ବିଭାଗୀୟ ଚାର୍ଟ। ପାରମ୍ପରିକ ଜ୍ୟୋତିଷରେ ଗ୍ରହର ସୂକ୍ଷ୍ମ ଶକ୍ତି, ଧର୍ମ ଏବଂ ବିଶେଷତଃ ବିବାହ/ଭାଗୀଦାରୀର ଅତିରିକ୍ତ ପ୍ରସଙ୍ଗ ପାଇଁ ଏହାକୁ ଦେଖାଯାଏ।',retro:'R ର ଅର୍ଥ',retroText:'ଗ୍ରହ ନାମ ପାଖରେ R ଥିଲେ retrograde ବୁଝାଏ—ପୃଥିବୀରୁ ଦେଖିଲେ ଗ୍ରହଟି ପଛକୁ ଯାଉଥିବା ପରି ଲାଗେ। ଏହା ପ୍ରକୃତ ଉଲ୍ଟା ଗତି ନୁହେଁ; ଦୃଶ୍ୟ ଜ୍ୟାମିତିକ ପ୍ରଭାବ।',houses:'12ଟି ଭାବର ସରଳ ଅର୍ଥ',accuracy:'ସଠିକତା ପାଇଁ ଆବଶ୍ୟକ',accuracyText:'ସଠିକ୍ ଜନ୍ମ ତାରିଖ, ସମ୍ଭବ ହେଲେ ମିନିଟ୍ ପର୍ଯ୍ୟନ୍ତ ସଠିକ୍ ଜନ୍ମସମୟ ଏବଂ ଠିକ୍ ଜନ୍ମସ୍ଥାନ ଅତ୍ୟନ୍ତ ଜରୁରୀ। କିଛି ମିନିଟ୍ ତଫାତ ଲଗ୍ନ/ଭାବ ସୀମାରେ ଫଳ ବଦଳାଇପାରେ। ଜ୍ୟୋତିଷୀୟ ଅର୍ଥ ପାରମ୍ପରିକ ବ୍ୟାଖ୍ୟା; ବୈଜ୍ଞାନିକ ଭାବେ ସିଦ୍ଧ ଭବିଷ୍ୟବାଣୀ ନୁହେଁ।'}:{title:'What your Kundli means',what:'What is this Kundli?',whatText:'This Kundli is a traditional Vedic-astrology map of the ascendant and planetary positions for your verified birth date, exact birth time and birthplace. It is used to interpret different areas of life.',lagna:'What does Lagna mean?',lagnaText:`Your Lagna is ${rashiUI(l,chart.ascendant.rashi)}. Lagna is the zodiac sign rising on the eastern horizon at birth. In traditional Jyotish it sets the starting point of all 12 houses and is associated with outward personality and life direction.`,moon:'Moon sign and Nakshatra',moonText:`The Moon is in ${moon?rashiUI(l,moon.rashi):'-'} and ${chart.panchang.nakshatra} Nakshatra. Traditionally the Moon is associated with mind, emotional response, habits and inner comfort; the Nakshatra adds a finer layer to that pattern.`,dasha:'What does the current Dasha mean?',dashaText:`The active sequence is ${grahaUI(l,d.currentLord)} Mahadasha / ${grahaUI(l,d.currentAntardashaLord)} Antardasha / ${grahaUI(l,d.currentPratyantarLord)} Pratyantar. Mahadasha is the long main period, Antardasha is a sub-period inside it, and Pratyantar is a shorter active sub-period. The current Mahadasha runs until ${date(d.currentEndsAt)}.`,panch:'What does Panchang show?',panchText:'Tithi is the lunar day based on the angular relationship of Sun and Moon; Paksha shows the waxing or waning half; Nakshatra is the Moon’s stellar sector; Yoga and Karana are additional traditional Panchang timing factors.',d9:'What is D9 / Navamsa?',d9Text:'D9 or Navamsa is a divisional chart derived from the main birth chart. Traditional Jyotish uses it as an additional view of planetary strength, dharma and especially marriage/partnership themes.',retro:'What does R mean?',retroText:'R beside a planet means retrograde: from Earth the planet appears to move backward against the sky. It is an apparent geometric effect rather than literal reverse motion; Jyotish gives it a separate interpretation.',houses:'Simple meaning of the 12 houses',accuracy:'What matters for accuracy',accuracyText:'Correct birth date, the most exact birth time available, and the correct birthplace are critical. A difference of a few minutes can matter near an Ascendant/house boundary. Astrological meaning remains a traditional interpretation, not a scientifically established prediction.'};return<><Text style={s.kicker}>{x.title.toUpperCase()}</Text><Card><Text style={s.gold}>{x.what}</Text><Text style={s.muted}>{x.whatText}</Text></Card><Card><Text style={s.gold}>{x.lagna}</Text><Text style={s.muted}>{x.lagnaText}</Text></Card><Card><Text style={s.gold}>{x.moon}</Text><Text style={s.muted}>{x.moonText}</Text></Card><Card><Text style={s.gold}>{x.dasha}</Text><Text style={s.muted}>{x.dashaText}</Text></Card><Card><Text style={s.gold}>{x.panch}</Text><Text style={s.muted}>{x.panchText}</Text></Card><Card><Text style={s.gold}>{x.d9}</Text><Text style={s.muted}>{x.d9Text}</Text></Card><Card><Text style={s.gold}>{x.retro}</Text><Text style={s.muted}>{x.retroText}</Text></Card><Card><Text style={s.gold}>{x.houses}</Text>{houses.map((h:string,i:number)=><Text key={i} style={s.bullet}>• {i+1}. {h}</Text>)}</Card><Card><Text style={s.gold}>{x.accuracy}</Text><Text style={s.muted}>{x.accuracyText}</Text></Card></>}
function PremiumScreen'''
text,count=re.subn(pattern,replacement,text,count=1,flags=re.S)
if count!=1: raise SystemExit('ChartScreen marker not found for Kundli explanation')
for needle in ('KundliMeaning','12 भावों का सरल अर्थ','12ଟି ଭାବର ସରଳ ଅର୍ଥ','What your Kundli means'):
    if needle not in text: raise SystemExit(f'Kundli explanation missing: {needle}')
path.write_text(text)
print('AstroSathi multilingual Kundli explanation installed')
